        addLog('\u7CFB\u7EDF\u521D\u59CB\u5316\u5931\u8D25: ' + error.message, 'error');
        
        // \u786E\u4FDD\u53CD\u4EE3\u914D\u7F6E\u6846\u663E\u793A
